import { useEffect, useState } from 'react';
import axios from 'axios';
import '../styles/messageCenter.css';

function MessageCenter() {
  const [messages, setMessages] = useState([]);
  const [form, setForm] = useState({ receiverId: '', itemId: '', content: '' });
  const senderId = localStorage.getItem('userId');

  // ✅ Fetch all messages where current user is the receiver
  const fetchReceivedMessages = async () => {
    try {
      const res = await axios.get(`${process.env.REACT_APP_API_URL}/api/messages/user`, {
        params: { userId: senderId }
      });

      const received = res.data.filter(
        msg => msg.receiverId === senderId || msg.receiverId?._id === senderId
      );

      setMessages(received);
    } catch (err) {
      console.error('Fetch error:', err.response?.data || err.message);
    }
  };

  useEffect(() => {
    fetchReceivedMessages();
    const interval = setInterval(fetchReceivedMessages, 5000);
    return () => clearInterval(interval);
  }, []);

  const sendMessage = async (e) => {
    e.preventDefault();
    if (!form.receiverId || !form.itemId || !form.content.trim()) return;
    try {
      await axios.post(`${process.env.REACT_APP_API_URL}/api/messages/send`, {
        ...form,
        senderId
      });
      setForm({ ...form, content: '' });
      fetchReceivedMessages();
    } catch (err) {
      console.error('Send error:', err.response?.data || err.message);
    }
  };
  const fetchConversation = useCallback(async () => {
  if (!form.receiverId) return;
  try {
    const res = await axios.get(`${process.env.REACT_APP_API_URL}/api/messages/between`, {
      params: { userA: senderId, userB: form.receiverId }
    });
    const receivedMessages = res.data.filter(msg =>
      msg.receiverId === senderId || msg.receiverId?._id === senderId
    );
    setMessages(receivedMessages);
  } catch (err) {
    console.error('Fetch error:', err.response?.data || err.message);
  }
}, [senderId, form.receiverId]);

  return (
    <div className="message-center">
      <h2>📥 Messages Received</h2>

      <form className="message-form" onSubmit={sendMessage}>
        <input
          placeholder="Receiver ID"
          value={form.receiverId}
          onChange={e => setForm({ ...form, receiverId: e.target.value })}
        />
        <input
          placeholder="Item ID"
          value={form.itemId}
          onChange={e => setForm({ ...form, itemId: e.target.value })}
        />
        <textarea
          placeholder="Type your message..."
          value={form.content}
          onChange={e => setForm({ ...form, content: e.target.value })}
        />
        <button type="submit">Send</button>
      </form>

      <div className="chat-thread">
        {messages.length === 0 ? (
          <p>No messages received yet.</p>
        ) : (
          messages.map(msg => {
            const senderLabel = msg.senderId?.username || 'User';
            return (
              <div key={msg._id} className="chat-bubble receiver">
                <div className="avatar">{senderLabel.charAt(0)}</div>
                <div className="bubble-content">
                  <p>{msg.content}</p>
                  <span className="meta">
                    From {senderLabel} • {new Date(msg.timestamp).toLocaleTimeString()}
                  </span>
                </div>
              </div>
            );
          })
        )}
      </div>
    </div>
  );
}

export default MessageCenter;
